def each_inspected_file(files)
  files.reduce(true) do |all_passed, file|
    offenses = process_file(file)
    yield file

    if offenses.any? { |o| considered_failure?(o) }
      break false if @options[:fail_fast]

      next false
    end

    all_passed
  end
end

